<?php
declare(strict_types=1); namespace Nshir; use PDO;
final class Uploads{public function __construct(private PDO $db){} public function saveAdImages(int $adId,array $files):void{if(empty($files['tmp_name'])||!is_array($files['tmp_name']))return;$root=dirname(__DIR__).'/storage/uploads';if(!is_dir($root))mkdir($root,0750,true);$max=((int)(getenv('UPLOAD_MAX_MB')?:8))*1024*1024;$fi=new \finfo(FILEINFO_MIME_TYPE);$sort=0;foreach($files['tmp_name'] as$i=>$tmp){if(($files['error'][$i]??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($files['size'][$i]??0)>$max)continue;$mime=$fi->file($tmp);$src=match($mime){'image/jpeg'=>@imagecreatefromjpeg($tmp),'image/png'=>@imagecreatefrompng($tmp),'image/webp'=>function_exists('imagecreatefromwebp')?@imagecreatefromwebp($tmp):false,default=>false};if(!$src)continue;$w=imagesx($src);$h=imagesy($src);$s=min(1,2200/max($w,$h));$nw=max(1,(int)round($w*$s));$nh=max(1,(int)round($h*$s));$dst=imagecreatetruecolor($nw,$nh);imagecopyresampled($dst,$src,0,0,0,0,$nw,$nh,$w,$h);$name=bin2hex(random_bytes(20)).'.webp';if(imagewebp($dst,$root.'/'.$name,82)){$q=$this->db->prepare('INSERT INTO ad_images(ad_id,path,width,height,sort_order) VALUES(?,?,?,?,?)');$q->execute([$adId,$name,$nw,$nh,$sort++]);}imagedestroy($src);imagedestroy($dst);}}}
